TYPES=frozenset(('KeyError','ValueError','TypeError','FileExistsError','PermissionError','TimeoutError','Blocked'))

def safe_error(error):
    if isinstance(error,Blocked) and len(error.args)==1 and isinstance(error.args[0],str) and error.args[0] in CODES:
        return error.args[0]
    name=type(error).__name__
    return 'exception_'+name if name in TYPES else 'blocked_unclassified'
